param([switch]$PassThru)
$ErrorActionPreference='Stop';$projectRoot=(Resolve-Path (Join-Path $PSScriptRoot '..\..')).Path;. (Join-Path $PSScriptRoot 'resolve-enterprise-powershell.ps1');$runtime=Get-EnterprisePowerShellCommand;$stamp=(Get-Date).ToString('yyyyMMddHHmmssfff');$releasePath=Join-Path $projectRoot ".qianlima/run-traces/enterprise-skills/releases/skill-$stamp.json";$creator=Join-Path $PSScriptRoot 'new-enterprise-skill-release.ps1';$transition=Join-Path $PSScriptRoot 'set-enterprise-skill-state.ps1';$taskId="skill-task-$stamp";$grantId="skill-grant-$stamp";$traceId="skill-trace-$stamp"
function Invoke-Child([string]$Script,[string[]]$Arguments){$raw=@(& $runtime -NoProfile -File $Script @Arguments 2>&1);[pscustomobject]@{code=$LASTEXITCODE;text=(($raw|ForEach-Object{$_.ToString()})-join"`n")}};function Get-Json($Result){try{return ($Result.text|ConvertFrom-Json)}catch{return $null}};function Add-Case($Cases,[string]$Name,[bool]$Passed){$Cases.Add([pscustomobject]@{name=$Name;passed=$Passed})};$cases=[System.Collections.Generic.List[object]]::new();$skillVersion='1.0.'+$stamp;$base=@('-SkillId','finance-readonly','-SkillVersion',$skillVersion,'-ArtifactRef',('skill://finance-readonly/'+$skillVersion),'-IntegrityHash',('sha256:'+('a'*64)),'-SourceRef','repository://approved/finance-readonly','-OwnerId','skill-owner','-TenantId','tenant-skill','-OrganizationId','org-skill','-ProjectId','project-skill','-Classification','internal_sanitized','-DeclaredCapabilities','read_finance;summarize','-DeclaredTools','read_ledger','-RiskLevel','L2','-RollbackRef','skill://finance-readonly/disabled','-TaskId',$taskId,'-GrantId',$grantId,'-TraceId',$traceId,'-OutputPath',$releasePath,'-PassThru');$created=Invoke-Child $creator $base;$createdJson=Get-Json $created;Add-Case $cases 'skill_candidate_has_no_authority' ($created.code-eq0-and$createdJson.execution_authority-eq$false-and$createdJson.installed-eq$false);$hash=(Get-FileHash -LiteralPath $releasePath -Algorithm SHA256).Hash;$skip=Invoke-Child $transition @('-ReleasePath',$releasePath,'-ToStatus','active','-ActorId','skill-owner','-TaskId',$taskId,'-GrantId',$grantId,'-TraceId',$traceId,'-EvidenceRef','receipt://active','-PassThru');$skipJson=Get-Json $skip;Add-Case $cases 'skill_cannot_skip_release_gates' ($skip.code-ne0-and$skipJson.reason-eq'invalid_skill_state_transition')
foreach($step in @(@('static_checked','receipt://static'),@('isolated_trial','receipt://trial'))){$r=Invoke-Child $transition @('-ReleasePath',$releasePath,'-ToStatus',$step[0],'-ActorId','skill-owner','-TaskId',$taskId,'-GrantId',$grantId,'-TraceId',$traceId,'-EvidenceRef',$step[1],'-PassThru');$rJson=Get-Json $r;Add-Case $cases ('skill_'+$step[0]+'_recorded') ($r.code-eq0-and$rJson.effective_status-eq$step[0])};$selfApprove=Invoke-Child $transition @('-ReleasePath',$releasePath,'-ToStatus','approved','-ActorId','skill-owner','-TaskId',$taskId,'-GrantId',$grantId,'-TraceId',$traceId,'-EvidenceRef','receipt://approval','-ApprovedBy','same-user','-IndependentVerifierId','same-user','-PassThru');$selfJson=Get-Json $selfApprove;Add-Case $cases 'skill_requires_separation_of_duties' ($selfApprove.code-ne0-and$selfJson.reason-eq'distinct_human_approver_and_independent_verifier_required')
$approved=Invoke-Child $transition @('-ReleasePath',$releasePath,'-ToStatus','approved','-ActorId','skill-owner','-TaskId',$taskId,'-GrantId',$grantId,'-TraceId',$traceId,'-EvidenceRef','receipt://approval','-ApprovedBy','business-owner','-IndependentVerifierId','security-verifier','-PassThru');$approvedJson=Get-Json $approved;$active=Invoke-Child $transition @('-ReleasePath',$releasePath,'-ToStatus','active','-ActorId','skill-owner','-TaskId',$taskId,'-GrantId',$grantId,'-TraceId',$traceId,'-EvidenceRef','receipt://activation','-PassThru');$activeJson=Get-Json $active;Add-Case $cases 'approved_skill_still_has_no_task_authority' ($approved.code-eq0-and$active.code-eq0-and$activeJson.execution_authority-eq$false-and$activeJson.tool_authority-eq$false-and$activeJson.data_scope_authority-eq$false)
$rollback=Invoke-Child $transition @('-ReleasePath',$releasePath,'-ToStatus','rolled_back','-ActorId','skill-owner','-TaskId',$taskId,'-GrantId',$grantId,'-TraceId',$traceId,'-EvidenceRef','receipt://rollback','-RollbackTargetRef','skill://finance-readonly/disabled','-PassThru');$rollbackJson=Get-Json $rollback;Add-Case $cases 'skill_rollback_is_append_only' ($rollback.code-eq0-and$rollbackJson.release_mutated-eq$false-and(Get-FileHash -LiteralPath $releasePath -Algorithm SHA256).Hash-eq$hash);$failed=@($cases|Where-Object{-not$_.passed});$out=[pscustomobject]@{passed=($failed.Count-eq0);cases=@($cases);installed=$false;execution_authority=$false;external_calls=$false;listeners_opened=$false;business_write=$false};if($PassThru){$out|ConvertTo-Json -Depth 10}else{$cases|Format-Table -AutoSize};if($failed.Count){throw('Enterprise Skill lifecycle regression failed: '+(($failed.name)-join', '))}
